<?php
declare(strict_types=1);
function pub_storage():string{$root=dirname(__DIR__).'/publication-files';if(is_link($root)||file_exists($root)&&!is_dir($root))crm_fail(503,'Хранилище недоступно.');if(!is_dir($root)&&!mkdir($root,0700))crm_fail(503,'Хранилище недоступно.');$real=realpath($root);if($real!==realpath(dirname(__DIR__)).'/publication-files')crm_fail(503,'Небезопасный путь хранилища.');if(PHP_SAPI!=='cli'){$web=realpath($_SERVER['DOCUMENT_ROOT']??'');if(!$web||$real===$web||str_starts_with($real,$web.'/'))crm_fail(503,'Хранилище должно находиться вне публичного каталога.');}return $real;}
function pub_media_path(array $f):string{if(!preg_match('/^[a-f0-9]{64}$/D',$f['storage_key']))crm_fail(404,'Файл не найден.');$p=pub_storage().'/'.$f['storage_key'];if(is_link($p)||!is_file($p)||filesize($p)!==(int)$f['size_bytes']||!hash_equals($f['checksum'],hash_file('sha256',$p)))crm_fail(404,'Файл не найден.');return $p;}
function pub_upload():array{
 $f=$_FILES['file']??null;if(!is_array($f)||$f['error']!==UPLOAD_ERR_OK||!is_uploaded_file($f['tmp_name']))crm_fail(422,'Выберите файл: изображение или видео до 8 МБ.');$size=filesize($f['tmp_name']);if(!$size||$size>8388608)crm_fail(422,'Файл пустой или превышает 8 МБ.');$name=$f['name'];if(!is_string($name)||mb_strlen($name)>190||preg_match('~[\x00-\x1f/\\\\]~',$name)||str_contains($name,'..'))crm_fail(422,'Проверьте имя файла.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$ext=strtolower(pathinfo($name,PATHINFO_EXTENSION));$types=['jpg'=>'image/jpeg','jpeg'=>'image/jpeg','png'=>'image/png','webp'=>'image/webp','mp4'=>'video/mp4','webm'=>'video/webm'];if(($types[$ext]??null)!==$mime)crm_fail(422,'Поддерживаются JPG, PNG, WebP, MP4 и WebM; тип проверяется по содержимому.');if(str_starts_with($mime,'image/')){$info=@getimagesize($f['tmp_name']);if(!$info||$info[0]>10000||$info[1]>10000||$info[0]*$info[1]>40000000)crm_fail(422,'Изображение слишком большое или повреждено.');}
 $key=bin2hex(random_bytes(32));$path=pub_storage().'/'.$key;if(!move_uploaded_file($f['tmp_name'],$path))crm_fail(503,'Не удалось сохранить файл.');chmod($path,0600);
 try{return crm_atomic(function()use($name,$mime,$size,$path,$key){if((int)crm_query('SELECT COALESCE(SUM(size_bytes),0) FROM nd_publication_media FOR UPDATE')->fetchColumn()+$size>268435456)crm_fail(422,'Квота медиатеки 256 МБ исчерпана. Файлы не удаляются автоматически.');crm_query('INSERT INTO nd_publication_media(storage_key,display_name,mime,size_bytes,checksum) VALUES (?,?,?,?,?)',[$key,$name,$mime,$size,hash_file('sha256',$path)]);return ['ok'=>true,'file'=>crm_query('SELECT id,display_name,mime,size_bytes,checksum FROM nd_publication_media WHERE id=?',[(int)db()->lastInsertId()])->fetch()];});}catch(Throwable $e){unlink($path);throw $e;}
}
function pub_stream(array $file):never{$path=pub_media_path($file);$size=(int)$file['size_bytes'];$start=0;$end=$size-1;$range=$_SERVER['HTTP_RANGE']??'';header('Content-Type: '.$file['mime']);header('X-Content-Type-Options: nosniff');header('Content-Disposition: inline; filename="media-'.$file['id'].'"');header('Accept-Ranges: bytes');header('Cache-Control: no-store');if($range!==''){if(!preg_match('/^bytes=([0-9]*)-([0-9]*)$/D',$range,$m)||$m[1]===''&&$m[2]===''){http_response_code(416);header('Content-Range: bytes */'.$size);exit;}if($m[1]===''){$start=max(0,$size-(int)$m[2]);}else{$start=(int)$m[1];if($m[2]!=='')$end=min($end,(int)$m[2]);}if($start>$end||$start>=$size){http_response_code(416);header('Content-Range: bytes */'.$size);exit;}http_response_code(206);header('Content-Range: bytes '.$start.'-'.$end.'/'.$size);}header('Content-Length: '.($end-$start+1));$h=fopen($path,'rb');fseek($h,$start);$left=$end-$start+1;while($left>0&&!feof($h)){$bytes=fread($h,min(65536,$left));if($bytes===false||$bytes==='')break;echo $bytes;$left-=strlen($bytes);}fclose($h);exit;}
